mappages["waterplane"].desc = "Plane of Water";
mappages["waterplane"].longdesc = `Everywhere, here, the sound of water. Lapping waves, smooth flowing rivers, rushing waterfalls. You appear just over what on Ellusus you would call a lake, in a pocket of space, and water flows out and in like arteries.`;
mappages["waterplane"].music = 'Ether';
mappages["waterplane"].savename = `Plane of Water`;
