    monster.setSpawnedBy(spawn);

    mapref.placeThing(25,26,spawn);


    spawn = localFactory.createTile("Spawner");
    spawngroup = ["KrakenNPC", "WaterElementalNPC", "WaterElementalNPC"];

    spawn.setSpawngroup(spawngroup);
    spawn.setMaxSpawns(2);
